/// The devices paired so far, each with its scope and a Revoke.
fn devices(cx: &mut DrawCtx<'_>, ui: &mut Ui) {
    theme::section(ui, "Paired devices");
    let devices = cx.core.devices().to_vec();
    if devices.is_empty() {
        ui.label(theme::meta_text(ui, "No device is paired."));
        return;
    }
    egui::Grid::new("remote-devices")
        .num_columns(5)
        .spacing([GAP, GAP])
        .show(ui, |ui| {
            for device in devices {
                ui.label(&device.name);
                let mut scope = device.scope;
                egui::ComboBox::from_id_salt(("remote-scope", device.id))
                    .selected_text(scope.word())
                    .show_ui(ui, |ui| {
                        ui.selectable_value(&mut scope, Scope::Read, "read");
                        ui.selectable_value(&mut scope, Scope::Control, "control");
                    });
                if scope != device.scope {
                    cx.dispatch(AppAction::SetDeviceScope {
                        device: device.id,
                        scope,
                    });
                }
                ui.label(theme::meta_text(
                    ui,
                    format!("paired {}", since_text(device.created)),
                ));
                ui.label(theme::meta_text(
                        self.pairing = None;
                        self.error("Pairing closed: three attempts failed.");
                    }
                }
            }
            AppAction::Paired(device) => {
                // The code is single-use: the window closes with the
                // first pairing made through it.
                self.pairing = None;
                self.devices.push(device);
                self.save_devices(out);
            }
            AppAction::DeviceSeen(id) => {
                let Some(device) = self.devices.iter_mut().find(|d| d.id == id) else {
                    return;
                };
                let stale = device.last_seen.is_none_or(|seen| {
                    now.wall
                        .duration_since(seen)
                        .is_ok_and(|d| d.as_secs() >= LAST_SEEN_SAVE_INTERVAL_SECS)
                });
                device.last_seen = Some(now.wall);
                if stale {
                    self.save_devices(out);
                }
            }
            AppAction::RevokeDevice(id) => {
                let before = self.devices.len();
                self.devices.retain(|d| d.id != id);
                if self.devices.len() != before {
                    self.save_devices(out);
                }
            }
            AppAction::SetDeviceScope { device, scope } => {
                if let Some(d) = self.devices.iter_mut().find(|d| d.id == device)
                    && d.scope != scope
                {
