/// The paired device behind a request's bearer token, or failing
/// that this host's cookie, seen now; or the refusal, which says
/// nothing of the host. A cookie travels with every request a
/// browser makes, so one that writes or upgrades must also say it
/// came from this host's own page.
fn authenticate(&mut self, request: &RemoteRequest) -> Result<PairedDevice, RemoteReply> {
    let by_cookie = request.bearer.is_none();
    let token = request.bearer.as_deref().or_else(|| {
        let id = self.core.identity()?.server_id;
        let header = request.cookie.as_deref()?;
        crate::core::cookie_value(header, &crate::core::cookie_name(id))
    });
    let Some(token) = token else {
        return Err(self.refuse(
