//! The Remote devices dialog: who this host is to a device, where it
//! listens, the pairing window with its QR code, and the devices paired
//! so far with their scope and a Revoke. Nothing here decides anything:
//! every change is an action, and the host's state is read back from
//! the core each frame.

use egui::{Context, RichText, Ui};

use super::{DrawCtx, GAP, cards::since_text, theme};
use crate::adapters::remote;
use crate::core::{AppAction, AppCore};
use crate::ports::remote::Scope;

/// What the dialog edits between frames: the name and port fields, the
/// scope the next pairing grants, and the QR image for the open code.
pub struct RemoteDraft {
    pub name: String,
    pub port: String,
    pub scope: Scope,
    /// The QR texture for the code it was made for.
    qr: Option<(String, egui::TextureHandle)>,
}

impl RemoteDraft {
    #[must_use]
    pub fn open(core: &AppCore) -> Self {
        let identity = core.identity();
        Self {
            name: identity.map(|i| i.server_name.clone()).unwrap_or_default(),
            port: identity
                .map(|i| i.listen.port.to_string())
                .unwrap_or_default(),
            scope: Scope::Read,
            qr: None,
        }
    }
}

            certificate: "MIIB".into(),
            spki_sha256: "cd".repeat(32),
            created: at(0),
            listen: Listen::default(),
        },
        devices: vec![device.clone()],
        rotated: false,
    });
    harness.state_mut().dispatched.clear();
    click(&mut harness, "Settings");
    click(&mut harness, "Remote devices…");
    harness.get_by_label("Remote devices");
    harness.get_by_label("Vision Pro");
    assert!(harness.query_by_label("Stop pairing").is_none());
    click(&mut harness, "Allow pairing for 5 minutes");
    let code = actions(&harness)
        .into_iter()
        .find_map(|a| match a {
            AppAction::OpenPairing { code, scope } => {
                assert_eq!(scope, Scope::Read);
                Some(code)
            }
            _ => None,
        })
        .expect("a pairing window was opened");
    assert_eq!(code.len(), 8);
    assert!(harness.state().core().pairing().is_some());
    // The code shows in two halves, as it is read aloud.
    let (a, b) = code.split_at(4);
    harness.get_by_label(format!("{a} {b}").as_str());
