        .unwrap()
        .spki_sha256
        .clone();
    Port {
        app,
        addr,
        client: pinned_client(&spki).unwrap(),
        control,
        host,
        secrets,
        remote,
        advertiser,
        transcripts,
        _dir: dir,
    }
