// --- the web control surface

/// A response with its head kept: the page tests read headers.
struct Raw {
    status: u16,
    headers: Vec<(String, String)>,
    body: String,
}

impl Raw {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(n, _)| n.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    }

    fn headers_named(&self, name: &str) -> Vec<&str> {
        self.headers
            .iter()
            .filter(|(n, _)| n.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
            .collect()
    }

    fn json(&self) -> serde_json::Value {
        serde_json::from_str(&self.body).unwrap_or_else(|e| panic!("{e}: {}", self.body))
    }
}

/// One request with `headers` as given (a `Host` is added when none is),
/// over a fresh pinned connection; the whole head comes back.
fn http_raw(
    addr: SocketAddr,
    config: &Arc<ClientConfig>,
    method: &str,
    path: &str,
    headers: &[(&str, &str)],
    body: &str,
) -> std::io::Result<Raw> {
    let tcp = TcpStream::connect(addr)?;
    tcp.set_read_timeout(Some(Duration::from_secs(10)))?;
    let conn = ClientConnection::new(
        Arc::clone(config),
        ServerName::try_from("localhost").unwrap(),
    )
    .map_err(std::io::Error::other)?;
    let mut s = StreamOwned::new(conn, tcp);
    while s.conn.is_handshaking() {
        s.conn.complete_io(&mut s.sock)?;
    }
    let mut head = format!("{method} {path} HTTP/1.1\r\n");
    if !headers.iter().any(|(n, _)| n.eq_ignore_ascii_case("host")) {
        head.push_str("Host: localhost\r\n");
    }
    for (n, v) in headers {
        head.push_str(&format!("{n}: {v}\r\n"));
    }
    head.push_str(&format!("Content-Length: {}\r\n\r\n{body}", body.len()));
    s.write_all(head.as_bytes())?;
    s.flush()?;
    let mut reader = BufReader::new(s);
    let mut line = String::new();
    reader.read_line(&mut line)?;
    let status: u16 = line
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, line.clone()))?;
    let mut out_headers = Vec::new();
    loop {
        let mut h = String::new();
        reader.read_line(&mut h)?;
        let h = h.trim_end();
        if h.is_empty() {
            break;
        }
        if let Some((n, v)) = h.split_once(':') {
            out_headers.push((n.trim().to_owned(), v.trim().to_owned()));
        }
    }
    let length = out_headers
        .iter()
        .find(|(n, _)| n.eq_ignore_ascii_case("content-length"))
        .and_then(|(_, v)| v.parse().ok())
        .unwrap_or(0);
    let mut body = vec![0; length];
    reader.read_exact(&mut body)?;
    Ok(Raw {
        status,
        headers: out_headers,
        body: String::from_utf8_lossy(&body).into_owned(),
    })
}

/// `http_raw` from a client thread while the app serves on this one.
fn raw(port: &mut Port, method: &str, path: &str, headers: &[(&str, &str)], body: &str) -> Raw {
    let addr = port.addr;
    let config = Arc::clone(&port.client);
    let owned: Vec<(String, String)> = headers
        .iter()
        .map(|(n, v)| ((*n).to_owned(), (*v).to_owned()))
        .collect();
    let (method, path, body) = (method.to_owned(), path.to_owned(), body.to_owned());
    let client = std::thread::spawn(move || {
        let refs: Vec<(&str, &str)> = owned.iter().map(|(n, v)| (n.as_str(), v.as_str())).collect();
        http_raw(addr, &config, &method, &path, &refs, &body)
    });
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    while !client.is_finished() {
        assert!(std::time::Instant::now() < deadline, "no reply");
        port.app.serve_pending();
        std::thread::sleep(Duration::from_millis(2));
    }
    client.join().unwrap().expect("http")
}

/// Pair as a browser does, with the cookie transport: the reply head.
fn pair_browser(port: &mut Port, code: &str, scope: Scope) -> Raw {
    port.app.dispatch(AppAction::OpenPairing {
        code: code.into(),
        scope,
    });
    let spki = port
        .remote
        .state()
        .identity
        .as_ref()
        .unwrap()
        .spki_sha256
        .clone();
    let body = serde_json::json!({
        "code": code,
        "device_name": "Safari on iPhone",
        "spki_sha256": spki,
        "transport": "cookie",
    });
    let reply = raw(port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(reply.status, 200, "{}", reply.body);
    reply
}

/// The `name=value` pair of a `Set-Cookie`, to send back as `Cookie`.
fn cookie_pair(reply: &Raw) -> String {
    let set = reply.header("set-cookie").expect("a Set-Cookie");
    set.split(';').next().unwrap().to_owned()
}

const CSP: &str = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";

#[test]
fn the_pages_are_served_to_a_stranger_with_their_headers_and_nothing_else_is() {
    let mut port = port();
    for (path, kind) in [
        ("/", "text/html; charset=utf-8"),
        ("/app.js", "text/javascript; charset=utf-8"),
        ("/app.css", "text/css; charset=utf-8"),
    ] {
        let r = raw(&mut port, "GET", path, &[], "");
        assert_eq!(r.status, 200, "{path}");
        assert_eq!(r.header("content-type"), Some(kind));
        assert_eq!(r.header("content-security-policy"), Some(CSP));
        assert_eq!(r.header("cache-control"), Some("no-store"));
        assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
        assert_eq!(r.header("referrer-policy"), Some("no-referrer"));
        assert_eq!(r.header("connection"), Some("close"));
        assert!(!r.body.is_empty());
    }
    // A query on a page path is ignored and not echoed.
    let r = raw(&mut port, "GET", "/?code=SECRET1", &[], "");
    assert_eq!(r.status, 200);
    assert!(!r.body.contains("SECRET1"));
    // Everything else outside the API is today's JSON 404.
    for (method, path) in [
        ("GET", "/favicon.ico"),
        ("POST", "/"),
        ("GET", "/api"),
        ("GET", "/app.js/x"),
    ] {
        let r = raw(&mut port, method, path, &[], "");
        assert_eq!(r.status, 404, "{method} {path}");
        assert_eq!(r.header("content-type"), Some("application/json"));
        assert_eq!(r.json()["error"]["code"], "not_found");
    }
    // Every JSON reply is no-store and nosniff too.
    let r = raw(&mut port, "GET", "/api/v1/info", &[], "");
    assert_eq!(r.header("cache-control"), Some("no-store"));
    assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
}

/// The `/api/v1/...` strings in `text`, each up to its closing quote.
fn api_strings(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = text;
    while let Some(at) = rest.find("/api/v1/") {
        let tail = &rest[at..];
        let end = tail.find(['\'', '"', '`']).unwrap_or(tail.len());
        out.push(tail[..end].to_owned());
        rest = &tail[end..];
    }
    out
}

