// --- the web control surface

/// A response with its head kept: the page tests read headers.
struct Raw {
    status: u16,
    headers: Vec<(String, String)>,
    body: String,
}

impl Raw {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(n, _)| n.eq_ignore_ascii_case(name))
            .map(|(_, v)| v.as_str())
    }

    fn json(&self) -> serde_json::Value {
        serde_json::from_str(&self.body).unwrap_or_else(|e| panic!("{e}: {}", self.body))
    }

    fn error_code(&self) -> String {
        self.json()["error"]["code"]
            .as_str()
            .unwrap_or("")
            .to_owned()
    }
}

/// One request with `headers` as given (a `Host` is added when none is),
/// over a fresh pinned connection; the whole head comes back.
fn http_raw(
    addr: SocketAddr,
    config: &Arc<ClientConfig>,
    method: &str,
    path: &str,
    headers: &[(String, String)],
    body: &str,
) -> std::io::Result<Raw> {
    let tcp = TcpStream::connect(addr)?;
    tcp.set_read_timeout(Some(Duration::from_secs(10)))?;
    let conn = ClientConnection::new(
        Arc::clone(config),
        ServerName::try_from("localhost").unwrap(),
    )
    .map_err(std::io::Error::other)?;
    let mut s = StreamOwned::new(conn, tcp);
    while s.conn.is_handshaking() {
        s.conn.complete_io(&mut s.sock)?;
    }
    let mut head = format!("{method} {path} HTTP/1.1\r\n");
    if !headers.iter().any(|(n, _)| n.eq_ignore_ascii_case("host")) {
        head.push_str("Host: localhost\r\n");
    }
    for (n, v) in headers {
        head.push_str(&format!("{n}: {v}\r\n"));
    }
    head.push_str(&format!("Content-Length: {}\r\n\r\n{body}", body.len()));
    s.write_all(head.as_bytes())?;
    s.flush()?;
    let mut reader = BufReader::new(s);
    let mut line = String::new();
    reader.read_line(&mut line)?;
    let status: u16 = line
        .split_whitespace()
        .nth(1)
        .and_then(|s| s.parse().ok())
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, line.clone()))?;
    let mut out_headers = Vec::new();
    loop {
        let mut h = String::new();
        reader.read_line(&mut h)?;
        let h = h.trim_end();
        if h.is_empty() {
            break;
        }
        if let Some((n, v)) = h.split_once(':') {
            out_headers.push((n.trim().to_owned(), v.trim().to_owned()));
        }
    }
    let length = out_headers
        .iter()
        .find(|(n, _)| n.eq_ignore_ascii_case("content-length"))
        .and_then(|(_, v)| v.parse().ok())
        .unwrap_or(0);
    let mut body = vec![0; length];
    reader.read_exact(&mut body)?;
    Ok(Raw {
        status,
        headers: out_headers,
        body: String::from_utf8_lossy(&body).into_owned(),
    })
}

fn pairs(headers: &[(&str, &str)]) -> Vec<(String, String)> {
    headers
        .iter()
        .map(|(n, v)| ((*n).to_owned(), (*v).to_owned()))
        .collect()
}

/// `http_raw` from a client thread while the app serves on this one.
fn raw(port: &mut Port, method: &str, path: &str, headers: &[(&str, &str)], body: &str) -> Raw {
    let addr = port.addr;
    let config = Arc::clone(&port.client);
    let headers = pairs(headers);
    let (method, path, body) = (method.to_owned(), path.to_owned(), body.to_owned());
    let client =
        std::thread::spawn(move || http_raw(addr, &config, &method, &path, &headers, &body));
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    while !client.is_finished() {
        assert!(std::time::Instant::now() < deadline, "no reply");
        port.app.serve_pending();
        std::thread::sleep(Duration::from_millis(2));
    }
    client.join().unwrap().expect("http")
}

/// Pair as a browser does, with the cookie transport: the reply head.
fn pair_browser(port: &mut Port, code: &str, scope: Scope) -> Raw {
    port.app.dispatch(AppAction::OpenPairing {
        code: code.into(),
        scope,
    });
    let spki = port
        .remote
        .state()
        .identity
        .as_ref()
        .unwrap()
        .spki_sha256
        .clone();
    let body = serde_json::json!({
        "code": code,
        "device_name": "Safari on iPhone",
        "spki_sha256": spki,
        "transport": "cookie",
    });
    let reply = raw(port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(reply.status, 200, "{}", reply.body);
    reply
}

/// The `name=value` pair of a `Set-Cookie`, to send back as `Cookie`.
fn cookie_pair(reply: &Raw) -> String {
    let set = reply.header("set-cookie").expect("a Set-Cookie");
    set.split(';').next().unwrap().to_owned()
}

const CSP: &str = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";

#[test]
fn the_pages_are_served_to_a_stranger_with_their_headers_and_nothing_else_is() {
    let mut port = port();
    for (path, kind) in [
        ("/", "text/html; charset=utf-8"),
        ("/app.js", "text/javascript; charset=utf-8"),
        ("/app.css", "text/css; charset=utf-8"),
    ] {
        let r = raw(&mut port, "GET", path, &[], "");
        assert_eq!(r.status, 200, "{path}");
        assert_eq!(r.header("content-type"), Some(kind));
        assert_eq!(r.header("content-security-policy"), Some(CSP));
        assert_eq!(r.header("cache-control"), Some("no-store"));
        assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
        assert_eq!(r.header("referrer-policy"), Some("no-referrer"));
        assert_eq!(r.header("connection"), Some("close"));
        assert!(!r.body.is_empty());
    }
    // A query on a page path is ignored and not echoed.
    let r = raw(&mut port, "GET", "/?code=SECRET1", &[], "");
    assert_eq!(r.status, 200);
    assert!(!r.body.contains("SECRET1"));
    // Everything else outside the API is today's JSON 404.
    for (method, path) in [
        ("GET", "/favicon.ico"),
        ("POST", "/"),
        ("GET", "/api"),
        ("GET", "/app.js/x"),
    ] {
        let r = raw(&mut port, method, path, &[], "");
        assert_eq!(r.status, 404, "{method} {path}");
        assert_eq!(r.header("content-type"), Some("application/json"));
        assert_eq!(r.error_code(), "not_found");
    }
    // Every JSON reply is no-store and nosniff too.
    let r = raw(&mut port, "GET", "/api/v1/info", &[], "");
    assert_eq!(r.header("cache-control"), Some("no-store"));
    assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
}

/// The `/api/v1/...` strings in `text`, each up to its closing quote.
fn api_strings(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = text;
    while let Some(at) = rest.find("/api/v1/") {
        let tail = &rest[at..];
        let end = tail.find(['\'', '"', '`']).unwrap_or(tail.len());
        out.push(tail[..end].to_owned());
        rest = &tail[end..];
    }
    out
}

#[test]
fn the_embedded_page_asks_only_for_what_the_host_serves() {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("web");
    let html = std::fs::read_to_string(dir.join("index.html")).unwrap();
    let js = std::fs::read_to_string(dir.join("app.js")).unwrap();
    // The embedded bytes are the files.
    for (path, text) in [("/", &html), ("/app.js", &js)] {
        assert_eq!(switchboard::adapters::web::page(path).unwrap().body, text);
    }
    // Guards: no inline script or style, no handler attributes, and
    // nothing that turns agent output into markup or code.
    assert!(!html.contains("style="));
    for tag in html.split("<script").skip(1) {
        let open = &tag[..tag.find('>').unwrap()];
        assert!(open.contains("src="), "an inline script: {open}");
    }
    assert!(!html.contains(" on"), "an event handler attribute");
    for banned in [
        "innerHTML",
        "outerHTML",
        "eval(",
        "document.write",
        "insertAdjacentHTML",
    ] {
        assert!(!js.contains(banned), "{banned}");
    }
    // `src` and `href` values are pages we serve, or `data:`.
    for attr in ["src=\"", "href=\""] {
        for part in html.split(attr).skip(1) {
            let value = &part[..part.find('"').unwrap()];
            assert!(
                value.starts_with("data:") || switchboard::adapters::web::page(value).is_some(),
                "{value}"
            );
        }
    }

    // Every route in app.js answers something other than `not_found`
    // for a paired device.
    let mut port = port();
    port.transcripts.set(Some(conversation(2)));
    let (_, project, session) = seed(&mut port, "");
    launched(&mut port, &session);
    let token = pair(&mut port, "ABCD2345", Scope::Control, "Pad");
    let auth = format!("Bearer {token}");
    let routes = api_strings(&js);
    assert!(routes.len() >= 8, "{routes:?}");
    for route in routes {
        let id = if route.contains("/projects/") {
            &project
        } else {
            &session
        };
        let path = route.replace("{id}", id);
        let (method, body) = if route.ends_with("/send") {
            ("POST", r#"{"op":"web1","text":"hi"}"#)
        } else if route.ends_with("/pair") {
            ("POST", "{}")
        } else {
            ("GET", "")
        };
        let r = raw(&mut port, method, &path, &[("Authorization", &auth)], body);
        assert_ne!(r.error_code(), "not_found", "{method} {path}: {}", r.body);
    }
}

#[test]
fn a_browser_pairs_into_a_cookie_named_for_the_host_and_the_script_never_holds_the_token() {
    let mut port = port();
    let reply = pair_browser(&mut port, "ABCD2345", Scope::Read);
    let body = reply.json();
    assert!(body["body"].get("token").is_none(), "{body}");
    let server_id = body["body"]["server_id"].as_str().unwrap().to_owned();
    let set = reply.header("set-cookie").unwrap();
    assert!(set.starts_with(&format!("__Host-sb-{server_id}=")), "{set}");
    for attr in ["HttpOnly", "Secure", "SameSite=Strict", "Path=/"] {
        assert!(set.contains(attr), "{attr} in {set}");
    }
    assert!(!set.to_ascii_lowercase().contains("domain"), "{set}");
    // The cookie alone reads `/me`.
    let cookie = cookie_pair(&reply);
    let me = raw(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!(me.status, 200, "{}", me.body);
    let me = me.json();
    assert_eq!(me["body"]["name"], "Safari on iPhone");
    assert_eq!(me["body"]["scope"], "read");
    assert_eq!(me["body"]["server_id"], server_id);
    // A cookie under the fixed name authenticates nothing, and neither
    // does a stranger's value under the right one.
    let (name, token) = cookie.split_once('=').unwrap();
    for header in [format!("__Host-sb={token}"), format!("{name}=nope")] {
        let r = raw(&mut port, "GET", "/api/v1/me", &[("Cookie", &header)], "");
        assert_eq!((r.status, r.error_code().as_str()), (401, "unauthorized"));
    }
    // A native pairing is unchanged: the token is in the body, no cookie.
    let spki = port
        .remote
        .state()
        .identity
        .as_ref()
        .unwrap()
        .spki_sha256
        .clone();
    port.app.dispatch(AppAction::OpenPairing {
        code: "QRST2345".into(),
        scope: Scope::Read,
    });
    let body = serde_json::json!({ "code": "QRST2345", "device_name": "CLI", "spki_sha256": spki });
    let r = raw(&mut port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert!(r.header("set-cookie").is_none());
    assert!(r.json()["body"]["token"].is_string());
}

#[test]
fn two_hosts_on_one_address_keep_each_others_cookies_apart() {
    let mut a = port();
    let mut b = port();
    let ra = pair_browser(&mut a, "ABCD2345", Scope::Read);
    let rb = pair_browser(&mut b, "ABCD2345", Scope::Read);
    let (ca, cb) = (cookie_pair(&ra), cookie_pair(&rb));
    assert_ne!(ca.split_once('=').unwrap().0, cb.split_once('=').unwrap().0);
    let both = format!("{ca}; {cb}");
    for (port, own) in [(&mut a, &ra), (&mut b, &rb)] {
        let me = raw(port, "GET", "/api/v1/me", &[("Cookie", &both)], "");
        assert_eq!(me.status, 200);
        assert_eq!(
            me.json()["body"]["server_id"],
            own.json()["body"]["server_id"]
        );
    }
    // Only the other host's cookie is a stranger's.
    let r = raw(&mut a, "GET", "/api/v1/me", &[("Cookie", &cb)], "");
    assert_eq!(r.status, 401);
}

#[test]
fn a_cookie_write_must_come_from_the_hosts_own_origin_and_a_bearer_needs_none() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let reply = pair_browser(&mut port, "ABCD2345", Scope::Control);
    let cookie = cookie_pair(&reply);
    let send = format!("/api/v1/sessions/{session}/send");
    let body = r#"{"op":"w1","text":"hello"}"#;
    for headers in [
        vec![("Cookie", cookie.as_str())],
        vec![
            ("Cookie", cookie.as_str()),
            ("Origin", "https://localhost:9"),
        ],
        vec![("Cookie", cookie.as_str()), ("Origin", "http://localhost")],
    ] {
        let r = raw(&mut port, "POST", &send, &headers, body);
        assert_eq!((r.status, r.error_code().as_str()), (403, "origin"));
    }
    let right = [("Cookie", cookie.as_str()), ("Origin", "https://localhost")];
    let r = raw(&mut port, "POST", &send, &right, body);
    assert_ne!(r.error_code(), "origin", "{}", r.body);
    // A bearer is exempt: a native client sends no `Origin`.
    let token = pair(&mut port, "WXYZ2345", Scope::Control, "CLI");
    let auth = format!("Bearer {token}");
    let r = raw(&mut port, "POST", &send, &[("Authorization", &auth)], body);
    assert_ne!(r.error_code(), "origin", "{}", r.body);
    // A read by cookie needs no `Origin`.
    let r = raw(&mut port, "GET", "/api/v1/waiting", &[("Cookie", &cookie)], "");
    assert_eq!(r.status, 200);
    // An upgrade by cookie: a foreign `Origin` is refused, the host's own is 101.
    for (origin, status) in [("https://evil.example", 403), ("https://localhost", 101)] {
        let headers = [
            ("Cookie", cookie.as_str()),
            ("Origin", origin),
            ("Upgrade", "websocket"),
            ("Connection", "Upgrade"),
            ("Sec-WebSocket-Key", "dGhlIHNhbXBsZSBub25jZQ=="),
            ("Sec-WebSocket-Version", "13"),
        ];
        let r = raw(&mut port, "GET", "/api/v1/events", &headers, "");
        assert_eq!(r.status, status, "{origin}");
    }
}

#[test]
fn me_follows_the_scope_and_a_removed_device_is_told_from_a_changed_host_by_info() {
    let mut port = port();
    let reply = pair_browser(&mut port, "ABCD2345", Scope::Read);
    let cookie = cookie_pair(&reply);
    let c = [("Cookie", cookie.as_str())];
    let me = raw(&mut port, "GET", "/api/v1/me", &c, "").json();
    assert_eq!(me["body"]["scope"], "read");
    let device = port.app.core().devices()[0].id;
    port.app.dispatch(AppAction::SetDeviceScope {
        device,
        scope: Scope::Control,
    });
    let me = raw(&mut port, "GET", "/api/v1/me", &c, "").json();
    assert_eq!(me["body"]["scope"], "control");

    let before = raw(&mut port, "GET", "/api/v1/info", &[], "").json();
    port.app.dispatch(AppAction::RevokeDevice(device));
    let r = raw(&mut port, "GET", "/api/v1/me", &c, "");
    assert_eq!((r.status, r.error_code().as_str()), (401, "unauthorized"));
    // What the page needs to say "removed": the same identity and key.
    let after = raw(&mut port, "GET", "/api/v1/info", &[], "").json();
    assert_eq!(after["body"]["server_id"], before["body"]["server_id"]);
    assert_eq!(after["body"]["spki_sha256"], before["body"]["spki_sha256"]);
}

#[test]
fn a_rotated_key_keeps_the_server_id_and_changes_the_key_the_page_compares() {
    let (old, _) = remote::make_identity(None, "Old", Listen::default()).unwrap();
    let store = FakeRemoteStore::default();
    store.state().identity = Some(old.clone());
    let mut port = port_with(FakeHost::default(), FakeSecrets::default(), store);
    let info = raw(&mut port, "GET", "/api/v1/info", &[], "").json();
    assert_eq!(info["body"]["server_id"], old.server_id.to_string());
    assert_ne!(info["body"]["spki_sha256"], old.spki_sha256);
}

#[test]
fn a_page_load_frees_its_slot_and_the_page_window_is_its_own() {
    let mut port = port();
    // Five loads in a row: `Connection: close` frees each slot.
    for _ in 0..=MAX_UNAUTHENTICATED {
        assert_eq!(raw(&mut port, "GET", "/", &[], "").status, 200);
        std::thread::sleep(Duration::from_millis(30));
    }
    // Four stalled strangers still leave a page request closed at accept.
    let strangers: Vec<TcpStream> = (0..MAX_UNAUTHENTICATED)
        .map(|_| TcpStream::connect(port.addr).expect("connect"))
        .collect();
    std::thread::sleep(Duration::from_millis(100));
    let result = http_raw(port.addr, &port.client, "GET", "/", &[], "");
    assert!(result.is_err(), "the pool is full of strangers");
    drop(strangers);
    drop(port);

    // 120 page requests a minute; the 121st is refused, `/info` and `/pair` are not.
    let mut port = port();
    let mut statuses = Vec::new();
    for _ in 0..121 {
        statuses.push(raw(&mut port, "GET", "/app.css", &[], "").status);
        // Let the thread give its slot back before the next accept.
        std::thread::sleep(Duration::from_millis(3));
    }
    assert_eq!(statuses.iter().filter(|s| **s == 200).count(), 120);
    assert_eq!(statuses[120], 429);
    assert_eq!(raw(&mut port, "GET", "/api/v1/info", &[], "").status, 200);
    assert_eq!(raw(&mut port, "POST", "/api/v1/pair", &[], "{}").status, 403);
}

#[test]
fn the_pages_logic_passes_its_own_tests_under_node() {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("web");
    let Ok(out) = std::process::Command::new("node")
        .arg("--test")
        .arg(dir.join("app.test.js"))
        .output()
    else {
        return; // no node here: skip, as the tmux tests do
    };
    assert!(
        out.status.success(),
        "{}{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
}

