    for (path, kind) in [
        ("/", "text/html; charset=utf-8"),
        ("/app.js", "text/javascript; charset=utf-8"),
        ("/app.css", "text/css; charset=utf-8"),
    ] {
        let r = raw(&mut port, "GET", path, &[], "");
        assert_eq!(r.status, 200, "{path}");
        assert_eq!(r.header("content-type"), Some(kind));
        assert_eq!(r.header("content-security-policy"), Some(CSP));
        assert_eq!(r.header("cache-control"), Some("no-store"));
        assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
        assert_eq!(r.header("referrer-policy"), Some("no-referrer"));
        assert_eq!(r.header("connection"), Some("close"));
        assert!(!r.body.is_empty());
    }
    // A query on a page path is ignored and not echoed.
    let r = raw(&mut port, "GET", "/?code=SECRET1", &[], "");
    assert_eq!(r.status, 200);
    assert!(!r.body.contains("SECRET1"));
    // Everything else outside the API is today's JSON 404.
    for (method, path) in [
        ("GET", "/favicon.ico"),
        ("POST", "/"),
        ("GET", "/api"),
        ("GET", "/app.js/x"),
    ] {
        let r = raw(&mut port, method, path, &[], "");
        assert_eq!(r.status, 404, "{method} {path}");
        assert_eq!(r.header("content-type"), Some("application/json"));
        assert_eq!(r.error_code(), "not_found");
    }
    // Every JSON reply is no-store and nosniff too.
    let r = raw(&mut port, "GET", "/api/v1/info", &[], "");
    assert_eq!(r.header("cache-control"), Some("no-store"));
    assert_eq!(r.header("x-content-type-options"), Some("nosniff"));
}

/// The `/api/v1/...` strings in `text`, each up to its closing quote.
fn api_strings(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = text;
    while let Some(at) = rest.find("/api/v1/") {
        let tail = &rest[at..];
        let end = tail.find(['\'', '"', '`']).unwrap_or(tail.len());
        out.push(tail[..end].to_owned());
        rest = &tail[end..];
    }
    out
}

#[test]
fn the_embedded_page_asks_only_for_what_the_host_serves() {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("web");
    let html = std::fs::read_to_string(dir.join("index.html")).unwrap();
    let js = std::fs::read_to_string(dir.join("app.js")).unwrap();
    // The embedded bytes are the files.
    for (path, text) in [("/", &html), ("/app.js", &js)] {
        assert_eq!(switchboard::adapters::web::page(path).unwrap().body, text);
    }
    // Guards: no inline script or style, no handler attributes, and
    // nothing that turns agent output into markup or code.
    assert!(!html.contains("style="));
    for tag in html.split("<script").skip(1) {
        let open = &tag[..tag.find('>').unwrap()];
        assert!(open.contains("src="), "an inline script: {open}");
    }
    assert!(!html.contains(" on"), "an event handler attribute");
    for banned in [
        "innerHTML",
        "outerHTML",
        "eval(",
        "document.write",
        "insertAdjacentHTML",
    ] {
        assert!(!js.contains(banned), "{banned}");
    }
    // `src` and `href` values are pages we serve, or `data:`.
    for attr in ["src=\"", "href=\""] {
        for part in html.split(attr).skip(1) {
            let value = &part[..part.find('"').unwrap()];
            assert!(
                value.starts_with("data:") || switchboard::adapters::web::page(value).is_some(),
                "{value}"
            );
        }
    }

    // Every route in app.js answers something other than `not_found`
    // for a paired device.
    let mut port = port();
    port.transcripts.set(Some(conversation(2)));
    let (_, project, session) = seed(&mut port, "");
    launched(&mut port, &session);
    let token = pair(&mut port, "ABCD2345", Scope::Control, "Pad");
    let auth = format!("Bearer {token}");
    let routes = api_strings(&js);
    assert!(routes.len() >= 8, "{routes:?}");
    for route in routes {
        let id = if route.contains("/projects/") {
            &project
        } else {
            &session
        };
        let path = route.replace("{id}", id);
        let (method, body) = if route.ends_with("/send") {
            ("POST", r#"{"op":"web1","text":"hi"}"#)
        } else if route.ends_with("/pair") {
            ("POST", "{}")
        } else {
            ("GET", "")
        };
        let r = raw(&mut port, method, &path, &[("Authorization", &auth)], body);
        assert_ne!(r.error_code(), "not_found", "{method} {path}: {}", r.body);
    }
}

#[test]
fn a_browser_pairs_into_a_cookie_named_for_the_host_and_the_script_never_holds_the_token() {
    let mut port = port();
    let reply = pair_browser(&mut port, "ABCD2345", Scope::Read);
    let body = reply.json();
    assert!(body["body"].get("token").is_none(), "{body}");
    let server_id = body["body"]["server_id"].as_str().unwrap().to_owned();
    let set = reply.header("set-cookie").unwrap();
    assert!(set.starts_with(&format!("__Host-sb-{server_id}=")), "{set}");
    for attr in ["HttpOnly", "Secure", "SameSite=Strict", "Path=/"] {
        assert!(set.contains(attr), "{attr} in {set}");
    }
    assert!(!set.to_ascii_lowercase().contains("domain"), "{set}");
    // The cookie alone reads `/me`.
    let cookie = cookie_pair(&reply);
    let me = raw(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!(me.status, 200, "{}", me.body);
    let me = me.json();
    assert_eq!(me["body"]["name"], "Safari on iPhone");
    assert_eq!(me["body"]["scope"], "read");
    assert_eq!(me["body"]["server_id"], server_id);
    // A cookie under the fixed name authenticates nothing, and neither
    // does a stranger's value under the right one.
    let (name, token) = cookie.split_once('=').unwrap();
    for header in [format!("__Host-sb={token}"), format!("{name}=nope")] {
        let r = raw(&mut port, "GET", "/api/v1/me", &[("Cookie", &header)], "");
        assert_eq!((r.status, r.error_code().as_str()), (401, "unauthorized"));
    }
    // A native pairing is unchanged: the token is in the body, no cookie.
    let spki = port
        .remote
        .state()
        .identity
        .as_ref()
        .unwrap()
        .spki_sha256
        .clone();
    port.app.dispatch(AppAction::OpenPairing {
        code: "QRST2345".into(),
        scope: Scope::Read,
    });
    let body = serde_json::json!({ "code": "QRST2345", "device_name": "CLI", "spki_sha256": spki });
    let r = raw(&mut port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert!(r.header("set-cookie").is_none());
    assert!(r.json()["body"]["token"].is_string());
}

#[test]
fn two_hosts_on_one_address_keep_each_others_cookies_apart() {
    let mut a = port();
    let mut b = port();
    let ra = pair_browser(&mut a, "ABCD2345", Scope::Read);
    let rb = pair_browser(&mut b, "ABCD2345", Scope::Read);
    let (ca, cb) = (cookie_pair(&ra), cookie_pair(&rb));
    assert_ne!(ca.split_once('=').unwrap().0, cb.split_once('=').unwrap().0);
    let both = format!("{ca}; {cb}");
    for (port, own) in [(&mut a, &ra), (&mut b, &rb)] {
        let me = raw(port, "GET", "/api/v1/me", &[("Cookie", &both)], "");
        assert_eq!(me.status, 200);
        assert_eq!(
            me.json()["body"]["server_id"],
            own.json()["body"]["server_id"]
        );
    }
    // Only the other host's cookie is a stranger's.
    let r = raw(&mut a, "GET", "/api/v1/me", &[("Cookie", &cb)], "");
    assert_eq!(r.status, 401);
}

#[test]
fn a_cookie_write_must_come_from_the_hosts_own_origin_and_a_bearer_needs_none() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let reply = pair_browser(&mut port, "ABCD2345", Scope::Control);
    let cookie = cookie_pair(&reply);
    let send = format!("/api/v1/sessions/{session}/send");
    let body = r#"{"op":"w1","text":"hello"}"#;
    for headers in [
        vec![("Cookie", cookie.as_str())],
        vec![
            ("Cookie", cookie.as_str()),
            ("Origin", "https://localhost:9"),
        ],
        vec![("Cookie", cookie.as_str()), ("Origin", "http://localhost")],
    ] {
        let r = raw(&mut port, "POST", &send, &headers, body);
        assert_eq!((r.status, r.error_code().as_str()), (403, "origin"));
    }
    let right = [("Cookie", cookie.as_str()), ("Origin", "https://localhost")];
    let r = raw(&mut port, "POST", &send, &right, body);
    assert_ne!(r.error_code(), "origin", "{}", r.body);
    // A bearer is exempt: a native client sends no `Origin`.
    let token = pair(&mut port, "WXYZ2345", Scope::Control, "CLI");
    let auth = format!("Bearer {token}");
    let r = raw(&mut port, "POST", &send, &[("Authorization", &auth)], body);
    assert_ne!(r.error_code(), "origin", "{}", r.body);
    // A read by cookie needs no `Origin`.
    let r = raw(&mut port, "GET", "/api/v1/waiting", &[("Cookie", &cookie)], "");
    assert_eq!(r.status, 200);
    // An upgrade by cookie: a foreign `Origin` is refused, the host's own is 101.
    for (origin, status) in [("https://evil.example", 403), ("https://localhost", 101)] {
        let headers = [
            ("Cookie", cookie.as_str()),
            ("Origin", origin),
            ("Upgrade", "websocket"),
            ("Connection", "Upgrade"),
            ("Sec-WebSocket-Key", "dGhlIHNhbXBsZSBub25jZQ=="),
            ("Sec-WebSocket-Version", "13"),
        ];
        let r = raw(&mut port, "GET", "/api/v1/events", &headers, "");
        assert_eq!(r.status, status, "{origin}");
    }
}

#[test]
fn me_follows_the_scope_and_a_removed_device_is_told_from_a_changed_host_by_info() {
    let mut port = port();
    let reply = pair_browser(&mut port, "ABCD2345", Scope::Read);
    let cookie = cookie_pair(&reply);
    let c = [("Cookie", cookie.as_str())];
    let me = raw(&mut port, "GET", "/api/v1/me", &c, "").json();
